// Generated by `just generate` from `src/plugins/claudetto/slices/prompt/adapters/mod.ts`. Edit the source and run `just generate`.
// The mod handlers of the `prompt` slice:
// `prompt.compose` replaces the shared `lean_body` section of the short prompt with the tailored text,
// because Claude Code 2.1.302 and later build that section raw and send only the session sections through `prompt.section`.
// `prompt.section` answers each other built-in section that has a transform with its shorter text,
// and the `context_management` section with the text of the compaction state.
// `tool.describe` shortens the `Agent` description and defers `ListAgents`.
// `agent.spawn` adds the rules for a subagent to the end of its task prompt.
// `prompt.attachment` and `command.describe` turn the `off` parts of the verdicts off.

import type { PluginOptions } from "claude-code";
import type { Handler } from "../../../kernel/slice.ts";
import { missLines, transformText } from "../domain/apply.ts";
import {
  CONTEXT_SECTION,
  compactionState,
  gatedText,
} from "../domain/compaction.ts";
import {
  LEAN_BODY,
  LEAN_BODY_SECTION,
  withBlock,
} from "../domain/lean-body.ts";
import { TOOL_AGENT } from "../prompts.ts";
import { TRANSFORMS } from "../transforms/index.ts";

/** The `userConfig` values of the plugin, which the generated `register` gives to `keepOptions`. */
const kept: { options: PluginOptions } = { options: {} };

/** Keeps the `userConfig` values of the plugin for the compaction gate. */
export const keepOptions = (options: PluginOptions): void => {
  kept.options = options;
};

// The answer to a section is the same for each call, so the cached answer keeps the prompt cache.
// `prompt.section` logs one debug line for each anchor that finds nothing.
export const onSection: Handler<"prompt.section"> = async ($, e, next) => {
  if (e.text === null) return next(e);
  if (e.name === CONTEXT_SECTION) {
    const state = compactionState(
      kept.options,
      await $.env.get("DISABLE_COMPACT"),
    );
    return state === "built-in" ? next(e) : { text: gatedText(e.text, state) };
  }
  if (!TRANSFORMS.has(e.name)) return next(e);
  for (const line of missLines(e.name, e.text)) $.ui.log(line, { to: "debug" });
  return { text: transformText(e.name, e.text) };
};

// A section of another id keeps its place, its scope, and its text, so the order and the cache boundary stay the engine's.
export const onCompose: Handler<"prompt.compose"> = async (_$, e, next) => {
  const { sections } = await next(e);
  return {
    sections: sections.map((s) =>
      s.id === LEAN_BODY_SECTION ? { ...s, text: LEAN_BODY } : s,
    ),
  };
};

// A subagent gets its system prompt from its agent body, so the rules go to the end of its task prompt.
export const onSpawn: Handler<"agent.spawn"> = (_$, e, next) =>
  next({ ...e, prompt: withBlock(e.prompt) });

// The `Agent` description is ours when it is shorter than the engine text, and `ListAgents` loads behind ToolSearch.
// The short prompt (`CLAUDE_CODE_SIMPLE_SYSTEM_PROMPT=1`) already shortens the `Bash` and `Read` descriptions.
// The `Agent(claude-code-guide)` and `Agent(statusline-setup)` deny rules of the settings drop the unused agents.
export const onToolDescribe: Handler<"tool.describe"> = async (_$, e, next) => {
  const answer = await next(e);
  if (e.tool === "ListAgents") return { ...answer, isDeferred: true };
  return TOOL_AGENT.length < answer.description.length
    ? { ...answer, description: TOOL_AGENT }
    : answer;
};

// The `off` verdicts: each hook below turns one built-in part off.
// The lists are in `domain/off.ts`, and the `filter` of each hook in `slice.ts` narrows the event to them.

/** An attachment of an `off` kind is left out of the request. */
// It takes no parameter, because the filter narrows the event to kinds that carry no `detail`, and `Handler` types the wider union.
export const onAttachment = (): { text: null } => ({ text: null });

/** A command of an `off` name leaves the typeahead and `/help`, and it still runs when typed in full. */
export const onCommandDescribe: Handler<"command.describe"> = (_$, e, next) =>
  next({ ...e, isHidden: true });
